INSERT INTO dump_descriptions (base_key, description) VALUES ('sugarrush1.0.3', 'Resizes selected UI textures for assignment, class-milestone, and challenge screens: most are halved, one upgrade icon is reduced to 128×128, and the “No Active Assignment” image is doubled.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
